package com.smartfile.controller;
import com.smartfile.entity.*;import com.smartfile.repository.*;import com.smartfile.security.JwtService;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.time.Year;import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {private final UserRepository users;private final DepartmentRepository departments;private final ApplicationRepository apps;private final WorkflowActionRepository actions;private final ComplaintRepository complaints;private final PasswordEncoder passwords;private final JwtService jwt;public ApiController(UserRepository u,DepartmentRepository d,ApplicationRepository a,WorkflowActionRepository w,ComplaintRepository c,PasswordEncoder p,JwtService j){users=u;departments=d;apps=a;actions=w;complaints=c;passwords=p;jwt=j;}
@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","SmartFile API");}
@PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String> body){var u=users.findByEmail(body.getOrDefault("email","").toLowerCase()).orElse(null);if(u==null||!passwords.matches(body.getOrDefault("password",""),u.passwordHash))return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));return ResponseEntity.ok(Map.of("token",jwt.issue(u.email,u.role),"email",u.email,"role",u.role,"name",u.fullName));}
@GetMapping("/applications") public List<SmartApplication> list(java.security.Principal principal){var u=users.findByEmail(principal.getName()).orElseThrow();if(u.role.equals("CITIZEN"))return apps.findAll().stream().filter(a->a.applicantName.equalsIgnoreCase(u.fullName)).toList();return apps.findAll();}
@GetMapping("/applications/{fileId}") public ResponseEntity<?> get(@PathVariable String fileId,java.security.Principal principal){var a=apps.findByFileId(fileId).orElse(null);if(a==null)return ResponseEntity.notFound().build();var u=users.findByEmail(principal.getName()).orElseThrow();if(u.role.equals("CITIZEN")&&!a.applicantName.equalsIgnoreCase(u.fullName))return ResponseEntity.status(403).body(Map.of("error","This application belongs to another applicant"));return ResponseEntity.ok(a);}
@PostMapping("/applications") public ResponseEntity<?> create(@RequestBody Map<String,String> body,java.security.Principal principal){String type=body.get("applicationType"),name=body.get("applicantName");if(type==null||type.isBlank()||name==null||name.isBlank())return ResponseEntity.badRequest().body(Map.of("error","applicationType and applicantName are required"));var user=users.findByEmail(principal.getName()).orElseThrow();if(user.role.equals("CITIZEN")&&!user.fullName.equalsIgnoreCase(name))return ResponseEntity.status(403).body(Map.of("error","Applicants may only submit applications for their own account"));String department=body.getOrDefault("department","Education");Department d=departments.findByNameIgnoreCase(department).orElseGet(()->departments.save(new Department(department)));SmartApplication a=new SmartApplication();a.applicationType=type;a.applicantName=name;a.department=d;a.priority=body.getOrDefault("priority","Normal");a.fileId=nextId();a.deadline=Instant.now().plusSeconds(172800);apps.save(a);actions.save(new WorkflowAction(a,principal.getName(),"SUBMITTED","Application received"));return ResponseEntity.status(201).body(a);}
@PostMapping("/applications/{fileId}/actions") public ResponseEntity<?> action(@PathVariable String fileId,@RequestBody Map<String,String> body,java.security.Principal principal){var user=users.findByEmail(principal.getName()).orElseThrow();if(!Set.of("ADMIN","CLERK","OFFICER").contains(user.role))return ResponseEntity.status(403).body(Map.of("error","This role cannot process workflow actions"));var a=apps.findByFileId(fileId).orElse(null);if(a==null)return ResponseEntity.notFound().build();String act=body.getOrDefault("action","").toUpperCase(),remarks=body.getOrDefault("remarks","");if((act.equals("REJECT")||act.equals("RETURN"))&&remarks.isBlank())return ResponseEntity.badRequest().body(Map.of("error","A reason is required"));if(!Set.of("APPROVE","REJECT","RETURN","FORWARD","REQUEST_DOCUMENTS").contains(act))return ResponseEntity.badRequest().body(Map.of("error","Unsupported workflow action"));a.status=switch(act){case "APPROVE"->"Approved";case "REJECT"->"Rejected";case "RETURN"->"Returned";case "FORWARD"->"Officer review";default->"Documents requested";};apps.save(a);actions.save(new WorkflowAction(a,principal.getName(),act,remarks));return ResponseEntity.ok(a);}
@GetMapping("/applications/{fileId}/history") public ResponseEntity<?> history(@PathVariable String fileId,java.security.Principal principal){var a=apps.findByFileId(fileId).orElse(null);if(a==null)return ResponseEntity.notFound().build();var u=users.findByEmail(principal.getName()).orElseThrow();if(u.role.equals("CITIZEN")&&!a.applicantName.equalsIgnoreCase(u.fullName))return ResponseEntity.status(403).body(Map.of("error","This application belongs to another applicant"));return ResponseEntity.ok(actions.findByApplicationFileIdOrderByCreatedAtAsc(fileId));}
@GetMapping("/track/{fileId}") public ResponseEntity<?> publicTrack(@PathVariable String fileId){return apps.findByFileId(fileId).<ResponseEntity<?>>map(a->ResponseEntity.ok(Map.of("fileId",a.fileId,"applicationType",a.applicationType,"department",a.department.name,"status",a.status,"submittedAt",a.submittedAt,"currentStage",a.currentStage))).orElseGet(()->ResponseEntity.notFound().build());}
@GetMapping("/complaints") public List<Complaint> complaintList(java.security.Principal p){var u=users.findByEmail(p.getName()).orElseThrow();return u.role.equals("ADMIN")?complaints.findAll():complaints.findAll().stream().filter(c->c.applicantName.equalsIgnoreCase(u.fullName)).toList();}
@PostMapping("/complaints") public ResponseEntity<?> complaint(@RequestBody Map<String,String> b,java.security.Principal p){String category=b.getOrDefault("applicationType",b.getOrDefault("category","Other")),name=b.get("applicantName");if(name==null||name.isBlank())return ResponseEntity.badRequest().body(Map.of("error","applicantName is required"));var u=users.findByEmail(p.getName()).orElseThrow();if(u.role.equals("CITIZEN")&&!u.fullName.equalsIgnoreCase(name))return ResponseEntity.status(403).body(Map.of("error","You may only file complaints for your account"));Complaint c=new Complaint();c.complaintId="CMP-"+String.format("%05d",complaints.count()+1);c.applicantName=name;c.category=category;c.description=b.getOrDefault("description","");return ResponseEntity.status(201).body(complaints.save(c));}
private synchronized String nextId(){String prefix="SF-"+Year.now().getValue()+"-";long n=apps.count()+1;String id;do{id=prefix+String.format("%04d",n++);}while(apps.findByFileId(id).isPresent());return id;}}
